SELECT "APPLICATION" AS "APPLICATION", AVG("JOB_DURATION_d") AS avg_duration 
FROM "default"."jobs" 
WHERE "@timestamp_date" >= TIMESTAMP '2026-03-25 00:00:00.000000' AND "@timestamp_date" < TIMESTAMP '2026-04-02 00:00:00.000000' GROUP BY "APPLICATION" ORDER BY AVG("JOB_DURATION_d") DESC 
 LIMIT 3;

SELECT DATE_TRUNC('day', "@timestamp_date") AS "@timestamp_date", "APPLICATION" AS "APPLICATION", AVG("JOB_DURATION_d") AS avg_duration 
FROM "default"."jobs" 
WHERE "@timestamp_date" >= TIMESTAMP '2026-03-25 00:00:00.000000' AND "@timestamp_date" < TIMESTAMP '2026-04-02 00:00:00.000000' AND ("APPLICATION" = 'COMPUTE' OR "APPLICATION" = 'INVOICING' OR "APPLICATION" = 'AUDIT') GROUP BY DATE_TRUNC('day', "@timestamp_date"), "APPLICATION" ORDER BY avg_duration DESC 
 LIMIT 1000;